describe('Particle.applyBehaviours', () => {
  test('applies all defined behaviours with correct time and index', () => {
    const particle = new Particle();

    const calls = [];
    const b1 = {
      applyBehaviour: (p, time, index) => {
        calls.push({ behaviour: 'b1', time, index });
        p.p.x = time;
      },
    };
    const b2 = {
      applyBehaviour: (p, time, index) => {
        calls.push({ behaviour: 'b2', time, index });
        p.v.y = index;
      },
    };

    particle.behaviours = [b1, b2];

    particle.applyBehaviours(7, 3);

    expect(particle.p.x).toBe(7);
    expect(particle.v.y).toBe(3);
    expect(calls).toEqual([
      { behaviour: 'b1', time: 7, index: 3 },
      { behaviour: 'b2', time: 7, index: 3 },
    ]);
